    /**
     * §27.9: a regeneration that stopped emitting sparse bodies must fail here.
     *
     * The count is asserted rather than left implicit so that dropping a sparse model from the
     * closure is a failure, not a quietly shorter suite.
     */
    @Test
    fun `every sparse body is covered`() {
        val cases = ManagementSparseBodiesGeneratedTest::class.java
            .declaredMethods.count { it.name.endsWith("sends only what was set") }
        assertEquals(18, cases,
            "one case per sparse body the schema closure declares")
    }

    /**
     * Asserts the encoded body's key set is exactly [expected], in any order.
     *
     * @param body the request body to render
     * @param serializer that body's generated serializer
     * @param expected the wire keys it must carry
     */
    private fun <T> assertKeys(
        body: T,
        serializer: kotlinx.serialization.KSerializer<T>,
        vararg expected: String,
    ) {
        val text = ManagementSupport.encodeBody("test", serializer, body)
        val actual = kotlinx.serialization.json.Json
            .parseToJsonElement(text).jsonObject.keys.sorted()
        assertEquals(
            expected.sorted(), actual,
            "${body!!::class.simpleName}: a sparse body must carry exactly the properties that were named",
        )
    }
